update crm_message_info
set titile = #{titile,jdbcType=VARCHAR},
  content = #{content,jdbcType=VARCHAR},
  send_time = #{sendTime,jdbcType=DATE},
  msg_type = #{msgType,jdbcType=INTEGER}
where id = #{id,jdbcType=BIGINT}

mapper.select:
SELECT msg.id as id, msg.titile as titile, msg.content as content, msg.send_time as sendTime, msg.msg_type as msgType, umsg.is_read as isRead, umsg.delete_flag as deleteFlag, umsg.is_send as isSend, suser.user_name AS sendName, ruser.user_name AS receiveName FROM crm_message_info AS msg INNER JOIN crm_user_msg AS umsg ON msg.id = umsg.msg_id INNER JOIN user_info AS suser ON suser.user_id = umsg.send_id INNER JOIN user_info AS ruser ON ruser.user_id = umsg.receive_id where 1=1
and umsg.is_read = #{isRead,jdbcType=INTEGER}
and umsg.delete_flag = #{deleteFlag,jdbcType=INTEGER}
and DATE_FORMAT(msg.send_time,'%Y-%m-%d') >= DATE_FORMAT(#{startDate,jdbcType=DATE},'%Y-%m-%d')
and DATE_FORMAT(msg.send_time,'%Y-%m-%d') <= DATE_FORMAT(#{endDate,jdbcType=DATE},'%Y-%m-%d')
and (umsg.send_id = #{userId,jdbcType=BIGINT} or umsg.receive_id = #{userId,jdbcType=BIGINT})
ORDER BY send_time DESC limit #{pageIndex} , #{pageSize}
